el.querySelector('#rosterClass').onchange=e=>{classFilter=e.target.value;body()};
el.querySelector('#addStudent').onsubmit=async e=>{e.preventDefault();const s=Object.fromEntries(new FormData(e.target));Object.keys(s).forEach(k=>s[k]=s[k].trim());if(!s.id||!s.name)return;if(!workspace.classes.some(g=>g.id===s.classId)){toast('请选择有效班级');return}const at=workspace.students.findIndex(x=>x.id===s.id);if(!editingStudent&&at>=0){toast('学号已存在');return}const previous=structuredClone(workspace.students);if(editingStudent&&at>=0)workspace.students[at]=s;else workspace.students.push(s);try{await save();editingStudent='';body();toast('学员档案已保存')}catch(error){workspace.students=previous;toast('保存失败，未修改学员档案：'+error.message)}};
el.querySelectorAll('[data-edit-student]').forEach(b=>b.onclick=()=>{editingStudent=b.dataset.editStudent;body()});const cancel=el.querySelector('#cancelStudentEdit');if(cancel)cancel.onclick=()=>{editingStudent='';body()};
el.querySelectorAll('[data-remove-student]').forEach(b=>b.onclick=async()=>{const id=b.dataset.removeStudent;if((data.exams||[]).some(e=>e.audience?.studentIds?.includes(id))){toast('该学员已被定向考试引用，请先调整考试分配');return}if(!confirm('从当前班级名单移除此学员？历史答卷会保留。'))return;const previous=workspace.students;workspace.students=workspace.students.filter(s=>s.id!==id);try{await save();if(editingStudent===id)editingStudent='';body()}catch(error){workspace.students=previous;toast('移除失败：'+error.message)}});
